// Loads assets/data/index.json (auto-generated by scripts/build_index.py
// via the GitHub Action on every push) and exposes small helpers.
window.loadData = function () {
  return fetch(SITE_CONFIG.basePath + "assets/data/index.json")
    .then((r) => r.json())
    .catch(() => ({ resources: [], bands: [], levelLabels: {} }));
};

window.resourceCardHTML = function (r, basePath) {
  const videoBtn = r.video_url
    ? `<a class="btn btn-outline" href="${r.video_url}" target="_blank" rel="noopener">▶ Watch video</a>`
    : "";
  return `
    <div class="resource-card">
      <div class="resource-main">
        <div class="resource-tags">
          <span class="tag">${r.levelLabel}</span>
          <span class="tag subject">${r.subject}</span>
        </div>
        <h3>${r.title}</h3>
        <p>${r.description || ""}</p>
        <div class="resource-meta">${r.size || ""}${r.date ? " · Added " + r.date : ""}</div>
      </div>
      <div class="resource-actions">
        ${videoBtn}
        <a class="btn btn-teal" href="${basePath}${r.file}" download>⬇ Download PDF</a>
      </div>
    </div>`;
};
